import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"Retro: truth parity — the store stops laundering a refuted derivation","description":"","frontmatter":{"title":"Retro: truth parity — the store stops laundering a refuted derivation","type":"retro","date":"2026-10-14T00:00:00.000Z"},"headers":[],"relativePath":"graphopt/project/retros/truth-parity.md","filePath":"vendored/graphopt/project/retros/truth-parity.md"}`),a={name:`graphopt/project/retros/truth-parity.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="retro-truth-parity-—-the-store-stops-laundering-a-refuted-derivation" tabindex="-1">Retro: truth parity — the store stops laundering a refuted derivation <a class="header-anchor" href="#retro-truth-parity-—-the-store-stops-laundering-a-refuted-derivation" aria-label="Permalink to “Retro: truth parity — the store stops laundering a refuted derivation”">​</a></h1><p><strong>Plan 0017 / ADR 0004</strong> — follow-up to <code>project/retros/derivable-gate.md</code> (commit c2acfbf) and the asymmetry <code>project/retros/shippable-audit.md</code> pinned. Date: 2026-10.</p><h2 id="the-residual-hole" tabindex="-1">The residual hole <a class="header-anchor" href="#the-residual-hole" aria-label="Permalink to “The residual hole”">​</a></h2><p>c2acfbf fixed the <em>gauntlet&#39;s</em> truth gate: <code>_truth_gate</code> reads <code>num_true is not False and (derivable or num_true is True)</code> unguarded, <code>clean and (derivable or equal &gt;= 1)</code> guarded — a measured counterexample outranks a derivation, and <code>derivable</code> may waive only the <em>absence</em> of a measured site.</p><p>But the store kept classifying verdict rows off the pipeline&#39;s own properties. <code>verdict_row</code> persisted</p><div class="language-python"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-dark:#888888;--shiki-light:#032F62;">&quot;</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#032F62;">verdict</span><span style="--shiki-dark:#888888;--shiki-light:#032F62;">&quot;</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">:</span><span style="--shiki-dark:#888888;--shiki-light:#032F62;"> &quot;</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#032F62;">SHIP</span><span style="--shiki-dark:#888888;--shiki-light:#032F62;">&quot;</span><span style="--shiki-dark:#0F0;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;"> if</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#24292E;"> ev</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">.</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#24292E;">shippable </span><span style="--shiki-dark:#0F0;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;">else</span><span style="--shiki-dark:#0F0;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;"> f</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#032F62;">&quot;no:</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#005CC5;">{</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#24292E;">ev</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">.</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#24292E;">no_ship_reason</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#005CC5;">}</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#032F62;">&quot;</span></span></code></pre></div><p>and <code>Evidence.shippable</code> consults <code>Evidence.truth</code> — still <code>derivable or num_true is True</code> (pipeline.py, sibling-owned). So a candidate the numeric oracle measured <strong>false</strong> on a real instance but saturation <strong>derived</strong> would persist <code>verdict=&quot;SHIP&quot;</code> whenever the pay gates were green. The store — the artifact the history report, <code>--ships</code>, <code>--flips</code> and the cache all read — disagreed with the gauntlet on exactly the case the derivable-gate change was about: a proof standing on a measured contradiction.</p><p><code>grep</code> confirms the store boundary was the only wave-through in this module: <code>_truth_gate</code> (post-c2acfbf) already refuses; <code>verdict_row</code> was the last place <code>derivable</code> could override a measured <code>num_true is False</code> inside evidence.py.</p><h2 id="the-fix" tabindex="-1">The fix <a class="header-anchor" href="#the-fix" aria-label="Permalink to “The fix”">​</a></h2><p><code>evidence._stored_verdict</code> — the persisted-verdict classifier — re-checks the measured site instead of trusting <code>ev.shippable</code>:</p><div class="language-python"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-dark:#0F0;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;">if</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#24292E;"> ev</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">.</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#24292E;">num_true </span><span style="--shiki-dark:#0F0;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;">is</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#005CC5;"> False</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">:</span></span>
<span class="line"><span style="--shiki-dark:#FFFFFF;--shiki-light:#24292E;">    over </span><span style="--shiki-dark:#0F0;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;">=</span><span style="--shiki-dark:#888888;--shiki-light:#032F62;"> &quot;</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#032F62;">; derivation overridden</span><span style="--shiki-dark:#888888;--shiki-light:#032F62;">&quot;</span><span style="--shiki-dark:#0F0;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;"> if</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#24292E;"> ev</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">.</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#24292E;">derivable </span><span style="--shiki-dark:#0F0;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;">else</span><span style="--shiki-dark:#888888;--shiki-light:#032F62;"> &quot;&quot;</span></span>
<span class="line"><span style="--shiki-dark:#0F0;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;">    return</span><span style="--shiki-dark:#0F0;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;"> f</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#032F62;">&quot;no:false (numeric oracle rejects</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#005CC5;">{</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#24292E;">over</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#005CC5;">}</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#032F62;">)&quot;</span></span>
<span class="line"><span style="--shiki-dark:#0F0;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;">return</span><span style="--shiki-dark:#888888;--shiki-light:#032F62;"> &quot;</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#032F62;">SHIP</span><span style="--shiki-dark:#888888;--shiki-light:#032F62;">&quot;</span><span style="--shiki-dark:#0F0;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;"> if</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#24292E;"> ev</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">.</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#24292E;">shippable </span><span style="--shiki-dark:#0F0;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;">else</span><span style="--shiki-dark:#0F0;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;"> f</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#032F62;">&quot;no:</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#005CC5;">{</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#24292E;">ev</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">.</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#24292E;">no_ship_reason</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#005CC5;">}</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#032F62;">&quot;</span></span></code></pre></div><ul><li>A measured <code>num_true is False</code> persists <code>no:false …</code> <strong>regardless</strong> of <code>derivable</code> — the store-side spelling of the gauntlet&#39;s <code>num_true is not False</code> clause.</li><li><code>derivable</code> may still waive an <em>absent</em> measurement (<code>num_true is None</code> → admissible when the other gates pass) — starvation is not a counterexample.</li><li>The reason stem reuses the pipeline&#39;s own vocabulary (<code>&quot;false (numeric oracle rejects)&quot;</code>), so a non-derivable measured-false row is spelled byte-identically to before; only the derivation-override case gains the <code>; derivation overridden</code> marker — the store&#39;s analogue of the gauntlet detail&#39;s <code>&quot;derivation overridden by a measured counterexample&quot;</code>.</li><li>The measured-false check runs <em>before</em> <code>no_ship_reason</code>, so a <code>num_true=False</code> record whose view verdict was <code>conditional</code> now reports the counterexample rather than the weaker &quot;conditional truth&quot; — a measured contradiction outranks the view oracle&#39;s guard hypothesis too.</li></ul><h2 id="what-was-deliberately-not-collapsed" tabindex="-1">What was deliberately NOT collapsed <a class="header-anchor" href="#what-was-deliberately-not-collapsed" aria-label="Permalink to “What was deliberately NOT collapsed”">​</a></h2><ul><li><strong><code>Evidence.truth</code> / <code>Evidence.shippable</code></strong> (pipeline.py) still let <code>derivable</code> override a measured false — the in-memory <em>candidate</em> bar is sibling-owned and unchanged. The divergence is now <em>contained</em>: it cannot reach the store, the reports, or a cache hit. A cache-served row rehydrates through <code>pipeline._evidence_from_row</code> and recomputes <code>truth</code> in memory, so the residual lives exactly where it did — flagged here, as the derivable-gate retro flagged it there.</li><li><strong><code>gap_gen.Found.truth</code></strong> (<code>base_truth or num_true is True or derivable</code>, gap_gen.py:668-676) is the <em>same</em> shape — a third instance of the waived-counterexample pattern, sibling-owned, flagged here the same way.</li><li><strong>The ambient-<code>cert_fail</code> asymmetry</strong> stays: the gauntlet charges only <em>attributable</em> cert failures while the pipeline&#39;s <code>shippable</code> demands <code>cert_fail == 0</code> — the deliberate looser direction the shippable audit documented. This change aligns only the measured-counterexample override; the closure asymmetry is untouched.</li><li><strong>The guarded-region sweep</strong> remains gauntlet-only: <code>unequal</code> / <code>rhs_err</code> / <code>guard_err</code> counts are not <code>Evidence</code> fields and never reach <code>verdict_row</code>, so at the store seam <code>num_true is False</code> is the whole measured-counterexample signal — exactly the unguarded branch of <code>_truth_gate</code> it now mirrors.</li></ul><h2 id="the-delta-—-measured" tabindex="-1">The delta — measured <a class="header-anchor" href="#the-delta-—-measured" aria-label="Permalink to “The delta — measured”">​</a></h2><p>Reclassifying every row in the real store (<code>$XDG_CACHE_HOME/catopt/evidence.db</code>, 132 verdict rows / 66 candidates) under the new rule:</p><table tabindex="0"><thead><tr><th>class</th><th>rows</th><th>verdict change</th></tr></thead><tbody><tr><td><code>numeric_true = 0</code></td><td>24</td><td><strong>0</strong> — all already <code>no:false</code>, all <code>derivable = 0</code></td></tr><tr><td><code>numeric_true = 0 AND derivable = 1</code></td><td>0</td><td>— the hole existed but no row sat in it</td></tr><tr><td><code>SHIP</code> rows</td><td>0</td><td>— nothing in this store ever shipped</td></tr><tr><td>total rows whose verdict changes</td><td><strong>0</strong></td><td></td></tr></tbody></table><p><strong>Zero reclassifications on the live store.</strong> The hole was latent, not populated: every measured-false row on record was non-derivable and already refused under the correct reason. The fix is prospective — the next <code>derivable ∧ num_true=False</code> candidate (the <code>channel_then_row_scale</code> class) can no longer persist <code>SHIP</code> on the derivation&#39;s strength. No record&#39;s stored <code>truth</code> columns (<code>numeric_true</code>, <code>derivable</code>) change at all — they were always honest; only the derived <code>verdict</code> label could lie.</p><h2 id="tests" tabindex="-1">Tests <a class="header-anchor" href="#tests" aria-label="Permalink to “Tests”">​</a></h2><p><code>tests/test_discovery_evidence.py</code>, new <em>Truth parity</em> section:</p><ul><li><code>test_verdict_row_measured_false_outranks_derivation</code> — <code>num_true=False, derivable=True</code>, all other gates green: <code>Evidence.shippable is True</code> (the pinned residual), the stored verdict is <code>no:false (…; derivation overridden)</code>.</li><li><code>test_verdict_row_measured_false_reason_unchanged</code> — non-derivable measured-false keeps the pre-existing spelling.</li><li><code>test_verdict_row_derivable_waives_only_absent_measurement</code> — <code>num_true=None, derivable=True</code> still stores <code>SHIP</code>.</li><li><code>test_stored_verdict_agrees_with_the_gauntlet</code> — the store verdict and <code>_truth_gate</code>&#39;s unguarded branch refuse the same record.</li><li><code>test_stored_verdict_round_trip_refused</code> — the refused row persists and <code>latest_verdicts</code> serves it back as <code>no:</code>.</li></ul><h2 id="gates" tabindex="-1">Gates <a class="header-anchor" href="#gates" aria-label="Permalink to “Gates”">​</a></h2><p><code>pytest tests/test_discovery_evidence.py tests/test_discovery_gauntlet.py tests/test_discovery_pipeline.py -q</code>; <code>ruff check</code>, <code>ruff format --check</code>, <code>ty check</code>, <code>radon_ratchet</code> — all clean. No new suppressions. <code>pipeline.py</code>, <code>oracle.py</code>, <code>intake.py</code>, <code>gap_gen.py</code>, <code>laws/</code> untouched.</p><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to “Limits”">​</a></h2><ul><li>The in-memory <code>Evidence.shippable</code>/<code>emit</code>/<code>intake</code> consumers still read the divergent property — a <code>derivable ∧ num_true=False</code> candidate can still <em>render</em> as shippable in a live pipeline run until pipeline.py gets the same clause. The store, the cache and the gauntlet no longer believe it.</li><li>Guarded (<code>cond</code>-carrying) records flow through <code>verdict_row</code> with only the unguarded signal available — region counts are gauntlet-only measurements, so a guarded object that is region-unclean but <code>num_true is True</code> still stores <code>SHIP</code> until a gauntlet run re-measures it. That was true before and after; closing it would mean persisting region counts in the verdict schema — a migration, not a clause.</li></ul>`,25)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};